const body = $input.first().json.body || $input.first().json;
const topics = Array.isArray(body.topics) ? body.topics : String(body.topics || '').split(',').map(s => s.trim()).filter(Boolean);
if (!topics.length) throw new Error('No topics supplied');
const cfg = $('Config').first().json;
return topics.map(t => ({ json: { topic: t, run_id: body.run_id || ('run-' + Date.now()), base: cfg.base, auto_approve: cfg.auto_approve_in_test, min_words: cfg.min_words } }));

// Deterministic QA gate, the model writes, code checks. Never publish on the model's say-so alone.
const d = $input.first().json.output;
const cfg = $('Loop topics').item.json;
const body = d.body || '';
const issues = [];
const words = body.split(/\s+/).filter(Boolean).length;
if (words < cfg.min_words) issues.push(`too short (${words} < ${cfg.min_words})`);
if (!/Sources:/.test(body)) issues.push('no sources section');
for (const bad of ['guaranteed', 'risk-free', '100%', 'best in the world']) if (body.toLowerCase().includes(bad)) issues.push('banned claim: ' + bad);
const required = ['Why it matters now', 'What to do this quarter'];
for (const r of required) if (!body.includes('## ' + r)) issues.push('missing section: ' + r);
const srcCount = (body.match(/https?:\/\//g) || []).length;
if (srcCount < 2) issues.push('fewer than 2 source links');
const usage = [$('Agent 2 · Outline (LLM)').item.json.usage, $input.first().json.usage].reduce((a,u)=>({input_tokens:a.input_tokens+(u?.input_tokens||0), output_tokens:a.output_tokens+(u?.output_tokens||0)}), {input_tokens:0, output_tokens:0});
return [{ json: { topic: cfg.topic, run_id: cfg.run_id, title: d.title, body, words, qa_pass: issues.length === 0, issues, usage, est_cost_usd: +((usage.input_tokens*3 + usage.output_tokens*15)/1e6).toFixed(4), base: cfg.base, auto_approve: cfg.auto_approve } }];

const q = $('Agent 4 · QA gate (deterministic checks)').item.json;
const pub = $input.first().json;
return [{ json: { topic: q.topic, title: q.title, words: q.words, qa_pass: q.qa_pass, issues: q.issues, published_url: pub.url || null, est_cost_usd: q.est_cost_usd, tokens: q.usage } }];
